type Resultado =
  | { estado: "cargando" }
  | { estado: "exito"; datos: string[] }
  | { estado: "error"; mensaje: string };

function renderizar(resultado: Resultado): string {
  switch (resultado.estado) {
    case "cargando": return "Cargando...";
    case "exito": return resultado.datos.join(", ");
    case "error": return resultado.mensaje;
  }
}

function imposible(valor: never): never {
  throw new Error("Estado no contemplado: " + valor);
}

function describir(resultado: Resultado): string {
  switch (resultado.estado) {
    case "cargando": return "Esperando";
    case "exito": return "Hay " + resultado.datos.length + " elementos";
    case "error": return resultado.mensaje;
    default: return imposible(resultado);
  }
}

